#nullable enable
namespace NoResponse
{
    using System;
    using System.Collections.Generic;
    using System.Globalization;
    using System.Linq;
    using System.Text.RegularExpressions;
    using Newtonsoft.Json;
    using Newtonsoft.Json.Linq;
    using NoResponse.Models.Shared;
    using NoResponse.Utils;

    /// <summary>
    /// Auth context adapters. Generated by tools/generate_auth_adapters.py; do not edit.
    ///
    /// Each adapter maps claims your backend has already verified into the
    /// auth_context of an assessment request. Pass verified claims, not a raw token.
    ///
    /// The mapping is the claim map (contracts/api/v1/fixtures/assessment-contract/
    /// auth-context-claim-map.json), run by the small interpreter below. Every SDK
    /// runs the same table and the same vectors. A claim that is missing, mistyped
    /// or out of range maps to absent, never to a stronger assurance.
    ///
    /// Claims and overrides are a dictionary or JObject of JSON values. Overrides
    /// use the auth_context field names, for example "email_verified". Every method
    /// throws ArgumentException when the claims have no valid issuer and subject or
    /// the provider is not a lowercase slug.
    /// </summary>
    public static class Auth
    {
        private const string ClaimMapJson = "{\"version\":1,\"kinds\":{\"id\":{\"pattern\":\"[A-Za-z0-9._:@/|+=~-]+\",\"maxLength\":256},\"audience\":{\"pattern\":\"[A-Za-z0-9._:/-]+\",\"maxLength\":256},\"role\":{\"pattern\":\"[A-Za-z0-9._:@/-]+\",\"maxLength\":64},\"method\":{\"pattern\":\"[A-Za-z0-9._:-]+\",\"maxLength\":32},\"issuer\":{\"pattern\":\"https://[\\\\x21-\\\\x7e]+\",\"maxLength\":256},\"time\":{\"pattern\":\"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\\\.[0-9]+)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])\",\"maxLength\":64}},\"slug\":\"[a-z0-9][a-z0-9._-]{1,31}\",\"constants\":{\"verified\":true,\"transport\":\"backend\"},\"base\":{\"issuer\":{\"op\":\"id\",\"kind\":\"issuer\",\"claims\":[\"iss\"],\"required\":true},\"subject\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"sub\"],\"required\":true},\"audiences\":{\"op\":\"list\",\"kind\":\"audience\",\"claims\":[\"aud\"],\"split\":\"whitespace\",\"max\":8},\"issued_at\":{\"op\":\"time\",\"claims\":[\"iat\"]},\"expires_at\":{\"op\":\"time\",\"claims\":[\"exp\"]},\"auth_time\":{\"op\":\"time\",\"claims\":[\"auth_time\"]},\"session_id\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"sid\"]},\"token_id\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"jti\"]}},\"providers\":{\"workos\":{\"fields\":{\"organization_id\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"org_id\"]},\"roles\":{\"op\":\"list\",\"kind\":\"role\",\"claims\":[\"roles\",\"role\"],\"split\":\"whitespace\",\"max\":32},\"scopes\":{\"op\":\"list\",\"kind\":\"role\",\"claims\":[\"permissions\"],\"split\":\"whitespace\",\"max\":32},\"impersonated\":{\"op\":\"actor\",\"claims\":[\"act\"]}}},\"clerk\":{\"disable\":[\"issued_at\"],\"fields\":{\"organization_id\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"o.id\",\"org_id\"]},\"roles\":{\"op\":\"list\",\"kind\":\"role\",\"claims\":[\"o.rol\",\"org_role\"],\"split\":\"none\",\"max\":32},\"scopes\":{\"op\":\"list\",\"kind\":\"role\",\"claims\":[\"o.per\",\"org_permissions\"],\"split\":\"comma_whitespace\",\"max\":32},\"impersonated\":{\"op\":\"actor\",\"claims\":[\"act\"]},\"mfa\":{\"op\":\"mfa_factor_age\",\"claim\":\"fva\",\"index\":1,\"unitSeconds\":60,\"maxSeconds\":315360000}}},\"auth0\":{\"fields\":{\"organization_id\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"org_id\"]},\"scopes\":{\"op\":\"list\",\"kind\":\"role\",\"claims\":[\"scope\",\"permissions\"],\"split\":\"whitespace\",\"max\":32},\"email_verified\":{\"op\":\"bool\",\"claims\":[\"email_verified\"]},\"phone_verified\":{\"op\":\"bool\",\"claims\":[\"phone_number_verified\"]},\"impersonated\":{\"op\":\"actor\",\"claims\":[\"act\"]},\"mfa\":{\"op\":\"mfa_methods\",\"kind\":\"method\",\"claim\":\"amr\",\"max\":8,\"mfaValue\":\"mfa\",\"ignore\":[\"pwd\"]}}},\"supabase\":{\"disable\":[\"auth_time\"],\"fields\":{\"session_id\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"session_id\"]},\"roles\":{\"op\":\"list\",\"kind\":\"role\",\"claims\":[\"role\"],\"split\":\"none\",\"max\":1},\"mfa\":{\"op\":\"mfa_aal\",\"claim\":\"aal\",\"present\":[\"aal2\"],\"absent\":[\"aal1\"],\"amr\":\"amr\",\"methodKey\":\"method\",\"factors\":{\"totp\":\"totp\",\"mfa/phone\":\"mfa:phone\",\"mfa/webauthn\":\"mfa:webauthn\",\"mfa/recovery_code\":\"mfa:recovery_code\"}},\"assurance_level\":{\"op\":\"marker\",\"value\":\"low\",\"when\":[{\"claim\":\"is_anonymous\",\"equals\":true},{\"claim\":\"app_metadata.provider\",\"equals\":\"anonymous\"}]}}},\"firebase\":{\"disable\":[\"session_id\",\"token_id\"],\"fields\":{\"tenant_id\":{\"op\":\"id\",\"kind\":\"id\",\"claims\":[\"firebase.tenant\"]},\"mfa\":{\"op\":\"mfa_factor\",\"kind\":\"method\",\"claim\":\"firebase.sign_in_second_factor\"},\"assurance_level\":{\"op\":\"marker\",\"value\":\"low\",\"when\":[{\"claim\":\"firebase.sign_in_provider\",\"equals\":\"anonymous\"}]}}},\"oidc\":{\"slugArgument\":true,\"fields\":{}}}}";
        private const double MaxTime = 253402300799.0;

        private static readonly JObject Map = JObject.Parse(ClaimMapJson, new JsonLoadSettings());
        private static readonly Regex Slug = new Regex("^(?:" + Map["slug"]!.Value<string>() + ")\\z", RegexOptions.CultureInvariant);
        private static readonly Regex Whitespace = new Regex("[ \\t\\r\\n\\f\\v]+", RegexOptions.CultureInvariant);
        private static readonly Regex CommaWhitespace = new Regex("[ \\t\\r\\n\\f\\v,]+", RegexOptions.CultureInvariant);
        private static readonly Dictionary<string, Regex> Kinds = ((JObject)Map["kinds"]!).Properties()
            .ToDictionary(p => p.Name, p => new Regex("^(?:" + p.Value["pattern"]!.Value<string>() + ")\\z", RegexOptions.CultureInvariant));

        /// <summary>The claim map this adapter runs, for tests.</summary>
        public static JObject ClaimMap => (JObject)Map.DeepClone();

        /// <summary>Map verified WorkOS AuthKit claims plus verified user or session record overrides.</summary>
        public static AuthContext FromWorkOS(object claims, object? overrides = null) =>
            Build("workos", "workos", claims, overrides);

        /// <summary>Map verified Clerk session claims. Pass Session.createdAt as the "session_created_at" override.</summary>
        public static AuthContext FromClerk(object claims, object? overrides = null) =>
            Build("clerk", "clerk", claims, overrides);

        /// <summary>Map verified Auth0 ID token, userinfo or normalised session claims. Do not pass an opaque API access token.</summary>
        public static AuthContext FromAuth0(object claims, object? overrides = null) =>
            Build("auth0", "auth0", claims, overrides);

        /// <summary>Map verified Supabase Auth access token claims (legacy HS256 secret or JWKS). Pass the user record's contact verification as overrides.</summary>
        public static AuthContext FromSupabase(object claims, object? overrides = null) =>
            Build("supabase", "supabase", claims, overrides);

        /// <summary>Map verified Firebase ID token claims from the Admin SDK VerifyIdTokenAsync. Custom claims never change the mapping.</summary>
        public static AuthContext FromFirebase(object claims, object? overrides = null) =>
            Build("firebase", "firebase", claims, overrides);

        /// <summary>Generic OIDC adapter for providers without a first-class helper. provider is a lowercase slug.</summary>
        public static AuthContext FromOIDC(string provider, object claims, object? overrides = null)
        {
            if (provider == null || !Slug.IsMatch(provider))
            {
                throw new ArgumentException("provider must be a lowercase provider slug", nameof(provider));
            }

            return Build("oidc", provider, claims, overrides);
        }

        private static string? Text(JToken? token) =>
            token != null && token.Type == JTokenType.String ? (string?)token : null;

        private static JToken? Lookup(JToken claims, string path)
        {
            JToken? current = claims;
            foreach (var key in path.Split('.'))
            {
                if (current is not JObject obj || !obj.TryGetValue(key, StringComparison.Ordinal, out var next))
                {
                    return null;
                }

                current = next;
            }

            return current;
        }

        private static bool IsNumber(JToken? token, out double number)
        {
            number = 0;
            if (token == null || (token.Type != JTokenType.Integer && token.Type != JTokenType.Float))
            {
                return false;
            }

            number = (double)token;
            return double.IsFinite(number);
        }

        private static bool Matches(string kind, JToken? token)
        {
            var text = Text(token);
            if (text == null)
            {
                return false;
            }

            var limit = Map["kinds"]![kind]!["maxLength"]!.Value<int>();
            return text.EnumerateRunes().Count() <= limit && Kinds[kind].IsMatch(text);
        }

        private static string Lower(string value) =>
            new string(value.Select(c => c >= 'A' && c <= 'Z' ? (char)(c + 32) : c).ToArray());

        private static IEnumerable<string> Strings(JToken? token) =>
            token == null ? Enumerable.Empty<string>() : token.Select(item => item.Value<string>()!);

        private static JToken? MapRule(JToken claims, JObject rule)
        {
            var op = rule["op"]!.Value<string>();
            switch (op)
            {
                case "id":
                    foreach (var path in Strings(rule["claims"]))
                    {
                        var value = Lookup(claims, path);
                        if (Matches(rule["kind"]!.Value<string>()!, value))
                        {
                            return value!.DeepClone();
                        }
                    }

                    return null;
                case "list":
                    return MapList(claims, rule);
                case "time":
                    foreach (var path in Strings(rule["claims"]))
                    {
                        var value = Lookup(claims, path);
                        if (IsNumber(value, out var number) && number >= 0 && number <= MaxTime)
                        {
                            // Whole UTC seconds; the fraction is truncated.
                            return new JValue(DateTimeOffset.FromUnixTimeSeconds((long)number).UtcDateTime
                                .ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", CultureInfo.InvariantCulture));
                        }

                        if (Matches("time", value))
                        {
                            return value!.DeepClone();
                        }
                    }

                    return null;
                case "bool":
                    foreach (var path in Strings(rule["claims"]))
                    {
                        var value = Lookup(claims, path);
                        if (value != null && value.Type == JTokenType.Boolean)
                        {
                            return value.DeepClone();
                        }
                    }

                    return null;
                case "actor":
                {
                    var value = Lookup(claims, Strings(rule["claims"]).First());
                    if (value is JObject obj)
                    {
                        return new JValue(new[] { "sub", "email" }.Any(key => !string.IsNullOrEmpty(Text(obj[key]))));
                    }

                    return new JValue(!string.IsNullOrEmpty(Text(value)));
                }
                case "mfa_factor_age":
                {
                    var value = Lookup(claims, rule["claim"]!.Value<string>()!);
                    var index = rule["index"]!.Value<int>();
                    if (value is not JArray list || list.Count <= index || !IsNumber(list[index], out var age))
                    {
                        return null;
                    }

                    var seconds = age * rule["unitSeconds"]!.Value<double>();
                    if (!(seconds >= 0 && seconds <= rule["maxSeconds"]!.Value<double>()))
                    {
                        return null;
                    }

                    return new JObject { ["present"] = true, ["age_seconds"] = (long)seconds };
                }
                case "mfa_aal":
                {
                    if (Lookup(claims, rule["claim"]!.Value<string>()!) is not JValue { Type: JTokenType.String } level)
                    {
                        return null;
                    }

                    var levelText = (string)level!;
                    if (Strings(rule["absent"]).Contains(levelText))
                    {
                        return new JObject { ["present"] = false };
                    }

                    if (!Strings(rule["present"]).Contains(levelText))
                    {
                        return null;
                    }

                    var methods = new List<string>();
                    if (Lookup(claims, rule["amr"]!.Value<string>()!) is JArray entries)
                    {
                        var factors = (JObject)rule["factors"]!;
                        foreach (var entry in entries)
                        {
                            var name = entry is JObject entryObject ? entryObject[rule["methodKey"]!.Value<string>()!] : entry;
                            if (name is JValue { Type: JTokenType.String } && factors[(string)name!] is JToken mapped
                                && !methods.Contains((string)mapped!))
                            {
                                methods.Add((string)mapped!);
                            }
                        }
                    }

                    var mfa = new JObject { ["present"] = true };
                    if (methods.Count > 0)
                    {
                        mfa["methods"] = new JArray(methods);
                    }

                    return mfa;
                }
                case "mfa_factor":
                {
                    var value = Lookup(claims, rule["claim"]!.Value<string>()!);
                    if (!Matches(rule["kind"]!.Value<string>()!, value))
                    {
                        return null;
                    }

                    return new JObject { ["present"] = true, ["methods"] = new JArray((string)value!) };
                }
                case "marker":
                    foreach (var test in (JArray)rule["when"]!)
                    {
                        var value = Lookup(claims, test["claim"]!.Value<string>()!);
                        if (value != null && JToken.DeepEquals(value, test["equals"]))
                        {
                            return rule["value"];
                        }
                    }

                    return null;
                case "mfa_methods":
                {
                    var value = Lookup(claims, rule["claim"]!.Value<string>()!);
                    if (value is not JArray list)
                    {
                        return null;
                    }

                    var kind = rule["kind"]!.Value<string>()!;
                    var kept = list.Where(item => Matches(kind, item)).Select(item => (string)item!)
                        .Take(rule["max"]!.Value<int>()).ToList();
                    var ignore = Strings(rule["ignore"]).ToList();
                    var methods = kept.Where(item => !ignore.Contains(Lower(item))).ToList();
                    if (methods.Count == 0)
                    {
                        return null;
                    }

                    var mfaValue = rule["mfaValue"]!.Value<string>();
                    return new JObject
                    {
                        ["present"] = kept.Any(item => Lower(item) == mfaValue),
                        ["methods"] = new JArray(methods),
                    };
                }
                default:
                    throw new InvalidOperationException("unknown claim map op " + op);
            }
        }

        private static JToken? MapList(JToken claims, JObject rule)
        {
            var split = rule["split"]?.Value<string>() ?? "whitespace";
            var kind = rule["kind"]!.Value<string>()!;
            var max = rule["max"]!.Value<int>();
            foreach (var path in Strings(rule["claims"]))
            {
                var value = Lookup(claims, path);
                IEnumerable<JToken> items = Enumerable.Empty<JToken>();
                if (value != null && value.Type == JTokenType.String)
                {
                    var text = (string)value!;
                    items = split == "none"
                        ? new JToken[] { value }
                        : (split == "comma_whitespace" ? CommaWhitespace : Whitespace).Split(text).Select(piece => (JToken)new JValue(piece));
                }
                else if (value is JArray array)
                {
                    items = array;
                }

                var kept = items.Where(item => Matches(kind, item)).Take(max).ToList();
                if (kept.Count > 0)
                {
                    return new JArray(kept.Select(item => item.DeepClone()));
                }
            }

            return null;
        }

        private static JObject Normalise(object? value)
        {
            if (value == null)
            {
                return new JObject();
            }

            // Re-read as text so a date value becomes a plain string.
            var text = JsonConvert.SerializeObject(value);
            return JsonConvert.DeserializeObject<JObject>(text, new JsonSerializerSettings { DateParseHandling = DateParseHandling.None })
                ?? new JObject();
        }

        private static AuthContext Build(string name, string provider, object claims, object? rawOverrides)
        {
            var normalisedClaims = Normalise(claims);
            var overrides = Normalise(rawOverrides);
            var spec = (JObject)Map["providers"]![name]!;
            var rules = new Dictionary<string, JObject>();
            foreach (var p in ((JObject)Map["base"]!).Properties())
            {
                rules[p.Name] = (JObject)p.Value;
            }

            foreach (var p in ((JObject)spec["fields"]!).Properties())
            {
                rules[p.Name] = (JObject)p.Value;
            }

            foreach (var field in Strings(spec["disable"]))
            {
                rules.Remove(field);
            }

            var wire = new JObject { ["provider"] = provider };
            foreach (var p in ((JObject)Map["constants"]!).Properties())
            {
                wire[p.Name] = p.Value.DeepClone();
            }

            foreach (var rule in rules)
            {
                var value = MapRule(normalisedClaims, rule.Value);
                if (value != null)
                {
                    wire[rule.Key] = value;
                }
            }

            foreach (var p in overrides.Properties())
            {
                if (p.Value.Type != JTokenType.Null)
                {
                    wire[p.Name] = p.Value.DeepClone();
                }
            }

            if (wire["audiences"] is JArray audiences && audiences.Count > 0 && !wire.ContainsKey("audience"))
            {
                wire["audience"] = audiences[0].DeepClone();
            }

            foreach (var key in new[] { "issuer", "subject" })
            {
                if (string.IsNullOrEmpty(Text(wire[key])))
                {
                    throw new ArgumentException("NoResponse auth context requires a verified issuer and subject");
                }
            }

            var settings = new JsonSerializerSettings
            {
                NullValueHandling = NullValueHandling.Ignore,
                DateParseHandling = DateParseHandling.None,
                Converters = Utilities.GetDefaultJsonDeserializers(),
            };
            try
            {
                return JsonConvert.DeserializeObject<AuthContext>(wire.ToString(Formatting.None), settings)
                    ?? throw new ArgumentException("NoResponse auth context could not be built");
            }
            catch (JsonException e)
            {
                throw new ArgumentException("NoResponse auth context could not be built: " + e.Message, e);
            }
        }
    }
}
